import{_ as t,o as a,c as o,ai as r}from"./chunks/framework.C33Uq6m-.js";const g=JSON.parse('{"title":"Analytics","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/analytics.md","filePath":"en/guide/analytics.md"}'),s={name:"en/guide/analytics.md"};function i(n,e,l,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h1><p>The Analytics page provides deep insight into your LLM usage patterns, performance characteristics, and response quality over time.</p><p><strong>Sidebar item:</strong> Analytics <strong>Route:</strong> <code>/analytics</code></p><h2 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h2><h3 id="response-quality" tabindex="-1">Response Quality <a class="header-anchor" href="#response-quality" aria-label="Permalink to &quot;Response Quality&quot;">​</a></h3><p><strong>Quality Over Turns</strong> shows how response quality evolves across a multi-turn conversation. Each assistant response is scored on a 0-5 scale based on:</p><ul><li><strong>Word count</strong> (40% weight) — longer responses score higher, capped at 50 words</li><li><strong>Vocabulary diversity</strong> (30% weight) — ratio of unique words to total words</li><li><strong>Non-repetition</strong> (30% weight) — lower 4-gram repetition scores higher</li></ul><p>Points are color-coded: green (3.5+), yellow (2-3.5), red (&lt; 2).</p><h3 id="latency-analysis" tabindex="-1">Latency Analysis <a class="header-anchor" href="#latency-analysis" aria-label="Permalink to &quot;Latency Analysis&quot;">​</a></h3><p>Three charts analyzing request performance:</p><ul><li><strong>Request Latency P50/P95/P99</strong> — windowed percentiles of <code>totalDurationMs</code> over sessions</li><li><strong>TTFT P50/P95/P99</strong> — same treatment for time-to-first-token</li><li><strong>Inter-Token Latency Distribution</strong> — histogram of token-to-token timing with OTel-recommended bucket boundaries</li></ul><h3 id="reliability" tabindex="-1">Reliability <a class="header-anchor" href="#reliability" aria-label="Permalink to &quot;Reliability&quot;">​</a></h3><ul><li><strong>Error Rate by Model</strong> — stacked bar chart showing errors by category per model</li><li><strong>Error Timeline</strong> — daily error count over time</li><li><strong>Load Duration Trend</strong> — model load times with cold start indicators (orange dots when &gt; 500ms)</li></ul><p>Error categories: connection, timeout, model not found, context exceeded, out of memory, tool error, cancelled.</p><h3 id="usage-patterns" tabindex="-1">Usage Patterns <a class="header-anchor" href="#usage-patterns" aria-label="Permalink to &quot;Usage Patterns&quot;">​</a></h3><ul><li><strong>Request Volume</strong> — daily bar chart of request count</li><li><strong>Model Distribution</strong> — doughnut chart showing proportion of requests per model</li><li><strong>Active Hours Heatmap</strong> — 7-day x 24-hour grid colored by request density</li></ul><h3 id="settings-impact" tabindex="-1">Settings Impact <a class="header-anchor" href="#settings-impact" aria-label="Permalink to &quot;Settings Impact&quot;">​</a></h3><p>Scatter plot showing correlation between temperature and tokens/sec. Each dot is a session. Requires at least 2 sessions with explicit temperature settings.</p><h3 id="model-memory" tabindex="-1">Model Memory <a class="header-anchor" href="#model-memory" aria-label="Permalink to &quot;Model Memory&quot;">​</a></h3><p>Timeline of recent model load events showing load duration and cold/warm start status. Cold starts (&gt; 500ms) are highlighted in orange.</p><h2 id="data-source" tabindex="-1">Data Source <a class="header-anchor" href="#data-source" aria-label="Permalink to &quot;Data Source&quot;">​</a></h2><p>All analytics are computed client-side from <code>SessionMetrics</code> already stored in IndexedDB. No additional data collection is needed. Charts update reactively when new sessions are recorded.</p>',22)])])}const p=t(s,[["render",i]]);export{g as __pageData,p as default};
